import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第107章 门带上","description":"","frontmatter":{},"headers":[],"relativePath":"第107章_门带上.md","filePath":"第107章_门带上.md"}'),o={name:"第107章_门带上.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第107章-门带上" tabindex="-1">第107章 门带上 <a class="header-anchor" href="#第107章-门带上" aria-label="Permalink to &quot;第107章 门带上&quot;">​</a></h1><p>那年冬天我们公司要培训，在澄江大学的老楼。</p><p>为什么借那个楼，因为便宜。</p><p>培训通知上写着：三号楼，二层，208。</p><p>我那天早到了四十分钟。</p><p>我那天不是故意早。</p><p>是地铁上有个故障，我在站台坐了二十分钟，然后我走出来又想，反正要等，我到那儿等。</p><p>我到那个楼是七点二十。</p><p>门开着。</p><p>我进去了。</p><p>我坐在最后一排靠门的那个位子。</p><p>我把包放在桌上，我拿出口袋里那个本子和笔。</p><p>我坐在那儿等。</p><p>那间教室很大，能坐六十几个。</p><p>我坐的位置在最后一排。</p><p>我那天上午干了什么呢。</p><p>我在算我们那一单的一个数。</p><p>她那边的账，十一月对不上，差了一百八。</p><p>我那天早上在算的是：我这边发了 231 单，她那边收了 229 单，那两单是不是漏发。</p><p>我在本子上列了三行。</p><p>列到第四行，我抬头。</p><p>我抬头那一下我才知道这不是我的班。</p><p>理由很实在：我前面那几排椅子是横过来的，横过来是有人要讲话，我们那个培训不要讲话，我们是坐电脑前。</p><p>而且这块黑板没擦。</p><p>黑板上有很多层。</p><p>那种黑板你擦不干净，一年下来它是灰绿的。</p><p>那一层灰绿上面，有一行字，是用白粉笔写的，写得很用力。</p><p>写得用力是因为那个人写字的时候手腕不按下去，他用指头。</p><p>那一行是英文。</p><p>前面半行被擦掉了，剩下的三个词留着。</p><p>我那天上午在那间教室里坐着，看那三个词看了很久。</p><p>我认得其中一个，因为那是一个很难的词。</p><p>我不认得整句。</p><p>我这个人英语一直不行。</p><p>我高三那年，我最怕的科目就是它。</p><p>我坐在那儿，我在想这是谁写的。</p><p>我最后决定：这是一个老师，他在上一节课上写了这一行，他下课忘了擦。</p><p>那天我的班在 214，我迟到了十七分钟。</p><p>讲师没有点名。</p><p>我坐下来的时候我旁边的一个人看了我一眼。</p><p>他说，208？</p><p>我说，我走错了。</p><p>他说，那里面现在没人。</p><p>我说，我知道。</p><p>他说，那楼现在没人管。</p><p>他说，我们以前在那儿上过一学期的课。</p><p>我说，哪个好教室。</p><p>他说，不好，那个教室的灯一半是坏的。</p><p>他说，但是那间教室有一件事好。</p><p>我说，什么。</p><p>他说，那个老师每节课在黑板上写一句话。</p><p>他说，他不讲那一句是什么，他写完就上课本。</p><p>他说，我们毕业那天，那个人把那句话留在黑板上，他没擦。</p><p>他说，他说留给下一届。</p><p>他说，下一届把它擦了。</p><p>他说，再下一届又有人写。</p><p>我坐在那个电脑前面。</p><p>那天上午我们那个培训讲的是一个系统怎么操作。</p><p>我一个字没进去。</p><p>我那天一整天想的都是那三个词。</p><p>那天中午我一个人回去了一遍 208。</p><p>我不是去拍那行字。</p><p>我是进去坐了半个小时。</p><p>我坐的还是最后一排靠门那个位子。</p><p>我坐下去以后发现一件事。</p><p>这个屋子里所有的椅子都是横过来的，只有我那一排有三把是正的。</p><p>那三把正的是给谁坐的？</p><p>我想了一下，没人坐。</p><p>那是下课的人随手推回去的。</p><p>我那天中午把那排椅子全部推正了。</p><p>我推完我坐在那个六十几个人的屋子里，我看了一中午正的椅子。</p><p>我下午上课以前，我又把它们全部推横了。</p><p>我推横它是因为那不是我的教室。</p><p>我那天晚上回去，我把那三个词写在纸上。</p><p>我拿手机查。</p><p>我查不出整句。</p><p>我第二天又查了一次。</p><p>第三天我放弃。</p><p>那个培训一共五天。</p><p>第三天下午又有一节在同一个楼。</p><p>我七点十分到，先去推 208。</p><p>那天锁了。</p><p>我拿手试了那个门把手，我试了两下。</p><p>第四天没锁。</p><p>里面有人在上课。</p><p>我在门口站着，我听了一分钟。</p><p>那不是一个班的课。</p><p>那是一群二十岁的人在讲一个我不懂的东西。</p><p>我下楼了。</p><p>第五天是最后一天，我们拍了一张合影。</p><p>我们公司那批一共二十三个人。</p><p>拍的时候我站在最边上。</p><p>我那只手拿着我的包。</p><p>我拿包那一下，我的脸转了一半。</p><p>后来那张照片发到群里。</p><p>我在里面找到了我自己。</p><p>我只能看到一个耳朵和半个鼻子。</p><p>我那天晚上看那张照片看了很久。</p><p>我想起我高二那年，她发给我十张合照，我挑了一张最糊的。</p><p>我那天晚上在那张新照片里，又看见了同一个自己。</p><p>我这辈子在所有合照里都是半个脸。</p><p>以前我以为那是因为我不会拍照。</p><p>那天我明白了，不是。</p><p>是因为我站在那里的时候，我手里一直拿着我的包。</p><p>我后来有一年，我把那三个词按我认识的词拼了一遍。</p><p>拼出来是一句关于把信留在桌子上的话。</p><p>两年以后我发现我拼错了，错得很远。我从头到尾不知道那行字讲的是什么。</p><p>我那天拼完，我把那张纸撕了。</p><p>我撕它是因为我知道这句话不是我听来的。</p><p>我是一个连整句都没看懂的人。</p><p>我把三个词拼成一句我听得懂的话，那不是那行字。</p><p>那是我把它改成我能用的样子。</p><p>我这个毛病我改不了。</p><p>我这个人我这辈子所有的记忆，进了我的脑子以后都要被我改一道。</p><p>我改完它才待得住。</p><p>那年培训结束我拿了一个证。</p><p>那个证后来被我压在仓库那个箱子的最底下。</p><p>压在什么下面呢。</p><p>压在那一张写着&quot;12月，18件&quot;的纸下面。</p><p>我妈那年贴的那张。</p><p>我那天从那个楼里出来的时候，走过那个 208。</p><p>门关着。</p><p>我推了一下。</p><p>我推那一下我不是要进去。</p><p>我是试它锁没锁。</p><p>没锁。</p><p>我拿手机拍了一张。</p><p>我拍的是那块黑板。</p><p>那块黑板上现在什么都没有。</p><p>它是灰绿的那一层。</p><p>我把手机收起来。</p><p>我把门带上。</p><p>那天我带门那一下用力了。</p><p>那个门合上的声音很闷。</p><p>我这一辈子关过很多门。</p><p>那一扇是第一次，我知道里面没人，我还是把它带上。</p><p>第二年春天，那个教室门上贴了一张纸。</p><p>纸上写两个字：库房。</p><p>我从那个门口过的时候，我手里拿着一个外卖。</p><p>我站在那里看了三秒。</p><p>我把那个外卖拿上去交给前台。</p><p>我下楼的时候我在想，那把锁现在在谁手上。</p><p>我这一辈子没能再进去那间屋子一次。</p>',143)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
